# secret_ref.py
@dataclass(frozen=True)
class SecretRef:
    namespace: str
    name: str

    def key(self, key: str) -> SecretKey:
        return SecretKey(secret=self, key=key)


@dataclass(frozen=True)
class SecretKey:
    secret: SecretRef
    key: str

    def value_from(self) -> k8s.EnvVarSource:
        """Also what a Helm env map takes: typed k8s structs render wire-shaped inside `any` values."""
        return k8s.EnvVarSource(secret_key_ref=k8s.SecretKeySelector(name=self.secret.name, key=self.key))

    def env_var(self, name: str) -> k8s.EnvVar:
        return k8s.EnvVar(name=name, value_from=self.value_from())

    def env_value(self, scope: Construct, id: str) -> EnvValue:
        return EnvValue.from_secret_value(
            SecretValue(secret=Secret.from_secret_name(scope, id, self.secret.name), key=self.key)
        )


# service_ref.py
@dataclass(frozen=True)
class Port:
    name: str
    number: int

    def container_port(self) -> ContainerPort: ...  # cdk8s-plus; k8s_container_port() for raw pods
    def service_port(self) -> ServicePort: ...  # cdk8s-plus; k8s_service_port() for raw Services


@dataclass(frozen=True)
class Pods:
    namespace: str
    labels: tuple[tuple[str, str], ...]

    @property
    def selector(self) -> dict[str, str]:
        return dict(self.labels)

    @property
    def cilium(self) -> dict[str, str]:
        return {"k8s:io.kubernetes.pod.namespace": self.namespace, **self.selector}

    def admit(self, *ports: int) -> CiliumNetworkPolicySpecIngress:
        """The server-side rule letting these Pods in; the server passes its own `pod_port`."""
        return IngressRule.from_endpoints(self.cilium, ports=ports)


@dataclass(frozen=True)
class ServiceRef:
    """A Service and the Pods behind it. A Service with several ports is several ServiceRefs sharing
    `name` and `pods`."""

    name: str
    port: Port  # the Service port clients dial: `url` and an HTTPRoute backendRef
    pods: Pods
    target_port: int | None = None  # the Pods' port where it differs (Helm charts; gatus 80 -> 8080)

    @property
    def pod_port(self) -> int:
        return self.port.number if self.target_port is None else self.target_port

    @property
    def labels(self) -> dict[str, str]:
        """The Service's own labels; a ServiceMonitor selects on these."""
        return self.pods.selector

    @property
    def host(self) -> str:
        return f"{self.name}.{self.pods.namespace}.svc"

    @property
    def fqdn(self) -> str:
        """For a host compared as a string, and for a client in a hostNetwork Pod, which does not
        get the cluster search path."""
        return f"{self.host}.cluster.local"

    @property
    def url(self) -> str:
        return f"http://{self.host}:{self.port.number}"

    def egress(self) -> CiliumNetworkPolicySpecEgress:
        """The client's rule. Cilium matches after socket-LB translation, so it names the Pods' port."""
        return EgressRule.to_endpoints(self.pods.cilium, self.pod_port)


@dataclass(frozen=True)
class HostNetworkServiceRef:
    """A Service in front of hostNetwork Pods. Cilium identifies their traffic by node, so there is no
    `egress()`; a client admits the node entities (agentplane/egress.py:107-108)."""

    name: str
    port: Port
    pods: Pods  # the Service's selector
