def api_objects(chart: Chart) -> list[ApiObject]:
    """Every ApiObject under `chart`; `Chart.api_objects` holds direct children only."""
    return [cast(ApiObject, node) for node in chart.node.find_all() if ApiObject.is_api_object(node)]


@dataclass(frozen=True)
class RenderedDirectory:
    """A directory `generation.write_directory` wrote, as its Flux Kustomization reads it."""

    artifact: ArtifactGeneratorSpecArtifacts
    decryption: KustomizationSpecDecryption | None  # set exactly when a sibling is SOPS ciphertext
    objects: tuple[ObjectId, ...]
    chart_kinds: frozenset[str]  # custom-resource kinds a HelmRelease here renders; `objects` cannot show them

    @property
    def kinds(self) -> frozenset[str]:
        return frozenset(obj.kind for obj in self.objects) | self.chart_kinds

    @property
    def stateful(self) -> bool:
        return any((obj.group, obj.kind) in STATEFUL_KINDS for obj in self.objects)

    def health_checks(self, *kinds: str) -> list[KustomizationSpecHealthChecks]:
        """For an admission target only (#7094 rule 4); replaces `flux.health_checks(chart, kinds)`."""
        return [
            KustomizationSpecHealthChecks(api_version=obj.api_version, kind=obj.kind, name=obj.name, namespace=obj.namespace)
            for obj in sorted((obj for obj in self.objects if obj.kind in kinds), key=lambda obj: kinds.index(obj.kind))
        ]


