    decryption: KustomizationSpecDecryption | None = None,
    # ... the other KustomizationSpec keywords, unchanged
) -> Kustomization:
    if isinstance(source, RenderedDirectory):
        if decryption is not None:
            raise ValueError(f"{name=}: a rendered directory derives its decryption; got {decryption=}")
        decryption = source.decryption
        if deletion_policy is None and source.stateful:
            deletion_policy = KustomizationSpecDeletionPolicy.ORPHAN  # a disposable cache passes MIRROR_PRUNE
        source = source.artifact
    match source:  # as today: an artifact derives sourceRef and path, and raises on an explicit path=
        ...


@jsii.implements(IValidation)  # a plain class: jsii sets __jsii_ref__, which a frozen dataclass refuses
class AdmissionGraph:
    """#7094 on the kustomizations chart, checked against what each node's directory renders."""

    def __init__(self, chart: Chart, directories: Sequence[RenderedDirectory]) -> None:
        self._chart = chart
        self._kinds = {directory.artifact.name: directory.kinds for directory in directories}  # by sourceRef name

    def validate(self) -> list[str]:
        nodes = [obj.to_json() for obj in api_objects(self._chart) if obj.kind == "Kustomization"]
        return [
            # (a) each rendered custom-resource kind reaches its provider in crd_layering.OPERATOR_CRDS
            *unreached_providers(nodes, self._kinds),
            # (b) each edge targets a CRD provider, a Fail-webhook operator or a postBuild source of the
            #     dependent, or is listed in ORDERING_EXCEPTIONS
            *unjustified_edges(nodes, self._kinds),
            # (c) wait, healthChecks and healthCheckExprs only on a node such an edge targets; each one gates
            *misplaced_gates(nodes, self._kinds),
        ]


