def write_directory(
    root: Path,
    artifact: ArtifactGeneratorSpecArtifacts,
    *chart_builders: Callable[[App], Chart],
    siblings: Sequence[str] = (),
    namespace: str | None = None,
    components: Sequence[str] = (),
    config_map_generator: Sequence[ConfigMapArgs] = (),
    chart_kinds: Sequence[str] = (),
    fleet: FleetExceptions = FleetExceptions(),
) -> RenderedDirectory:
    """One component's directory (#7094 rule 3)."""
    directory = artifact_directory(artifact)
    if len(artifact.copy) != 1:
        raise ValueError(f"{artifact.name=}: the writer lists one directory; this artifact also copies shared bases")
    charts = write_charts(root, directory, *chart_builders, fleet=fleet)
    write_yaml(
        root / directory / "kustomization.yaml",
        kustomize_kustomization(
            resources=[*(f"{Names.to_dns_label(chart)}.k8s.yaml" for chart in charts), *siblings],
            namespace=namespace,
            components=components,
            config_map_generator=config_map_generator,
        ),
    )
    return RenderedDirectory(
        artifact=artifact,
        decryption=sops_decryption(siblings),
        objects=tuple(
            ObjectId(api_version=obj.api_version, kind=obj.kind, name=obj.name, namespace=obj.metadata.namespace)
            for chart in charts
            for obj in api_objects(chart)
        ),
        chart_kinds=frozenset(chart_kinds),
    )


